macro_rules! repr_nullable_ptr {
    () => {
        # [doc = " Check if this enum can be safely exported based on the \"nullable pointer optimization\". If it"] # [doc = " can, return the type that `ty` can be safely converted to, otherwise return `None`."] # [doc = " Currently restricted to function pointers, boxes, references, `core::num::NonZero`,"] # [doc = " `core::ptr::NonNull`, and `#[repr(transparent)]` newtypes."] pub (crate) fn repr_nullable_ptr < 'tcx > (tcx : TyCtxt < 'tcx > , typing_env : ty :: TypingEnv < 'tcx > , ty : Ty < 'tcx > ,) -> Option < Ty < 'tcx > > { debug ! ("is_repr_nullable_ptr(tcx, ty = {:?})" , ty) ; match ty . kind () { ty :: Adt (ty_def , args) => { let field_ty = match & ty_def . variants () . raw [..] { [var_one , var_two] => match (& var_one . fields . raw [..] , & var_two . fields . raw [..]) { ([] , [field]) | ([field] , []) => field . ty (tcx , args) , ([field1] , [field2]) => { let ty1 = field1 . ty (tcx , args) ; let ty2 = field2 . ty (tcx , args) ; if is_niche_optimization_candidate (tcx , typing_env , ty1) { ty2 } else if is_niche_optimization_candidate (tcx , typing_env , ty2) { ty1 } else { return None ; } } _ => return None , } , _ => return None , } ; if ! ty_is_known_nonnull (tcx , typing_env , field_ty) { return None ; } let compute_size_skeleton = | t | SizeSkeleton :: compute (t , tcx , typing_env) . ok () ; if ! compute_size_skeleton (ty) ? . same_size (compute_size_skeleton (field_ty) ?) { bug ! ("improper_ctypes: Option nonnull optimization not applied?") ; } let field_ty_layout = tcx . layout_of (typing_env . as_query_input (field_ty)) ; if field_ty_layout . is_err () && ! field_ty . has_non_region_param () { bug ! ("should be able to compute the layout of non-polymorphic type") ; } let field_ty_abi = & field_ty_layout . ok () ? . backend_repr ; if let BackendRepr :: Scalar (field_ty_scalar) = field_ty_abi { match field_ty_scalar . valid_range (& tcx) { WrappingRange { start : 0 , end } if end == field_ty_scalar . size (& tcx) . unsigned_int_max () - 1 => { return Some (get_nullable_type (tcx , typing_env , field_ty) . unwrap ()) ; } WrappingRange { start : 1 , .. } => { return Some (get_nullable_type (tcx , typing_env , field_ty) . unwrap ()) ; } WrappingRange { start , end } => { unreachable ! ("Unhandled start and end range: ({}, {})" , start , end) } } ; } None } ty :: Pat (base , pat) => get_nullable_type_from_pat (tcx , typing_env , * base , * pat) , _ => None , } }
    };
}

repr_nullable_ptr!();